const PlasmicDescendants = {
  root: [
    "root",
    "iconWrapper",
    "titleWrapper",
    "descriptionWrapper",
    "activeGridHoverStyle",
    "lottie"
  ],
  iconWrapper: ["iconWrapper"],
  titleWrapper: ["titleWrapper"],
  descriptionWrapper: ["descriptionWrapper"],
  activeGridHoverStyle: ["activeGridHoverStyle", "lottie"],
  lottie: ["lottie"]
} as const;
type NodeNameType = keyof typeof PlasmicDescendants;
type DescendantsType<T extends NodeNameType> =
  (typeof PlasmicDescendants)[T][number];
type NodeDefaultElementType = {
  root: "div";
  iconWrapper: "div";
  titleWrapper: "h3";
  descriptionWrapper: "p";
  activeGridHoverStyle: "div";
  lottie: typeof LottieWrapper;
};

type ReservedPropsType = "variants" | "args" | "overrides";
type NodeOverridesType<T extends NodeNameType> = Pick<
  PlasmicInfoCard__OverridesType,
  DescendantsType<T>
>;
type NodeComponentProps<T extends NodeNameType> =
  // Explicitly specify variants, args, and overrides as objects
  {
    variants?: PlasmicInfoCard__VariantsArgs;
    args?: PlasmicInfoCard__ArgsType;
    overrides?: NodeOverridesType<T>;
  } &
    // Specify variants directly as props
    Omit<PlasmicInfoCard__VariantsArgs, ReservedPropsType> &
    // Specify args directly as props
    Omit<PlasmicInfoCard__ArgsType, ReservedPropsType> &
    // Specify overrides for each element directly as props
    Omit<
      NodeOverridesType<T>,
      ReservedPropsType | VariantPropType | ArgPropType
    > &
    // Specify props for the root element
    Omit<
      Partial<React.ComponentProps<NodeDefaultElementType[T]>>,
      ReservedPropsType | VariantPropType | ArgPropType | DescendantsType<T>
    >;

function makeNodeComponent<NodeName extends NodeNameType>(nodeName: NodeName) {
  type PropsType = NodeComponentProps<NodeName> & { key?: React.Key };
  const func = function <T extends PropsType>(
    props: T & StrictProps<T, PropsType>
  ) {
    const { variants, args, overrides } = React.useMemo(
      () =>
        deriveRenderOpts(props, {
          name: nodeName,
          descendantNames: PlasmicDescendants[nodeName],
          internalArgPropNames: PlasmicInfoCard__ArgProps,
          internalVariantPropNames: PlasmicInfoCard__VariantProps
        }),
      [props, nodeName]
    );
    return PlasmicInfoCard__RenderFunc({
      variants,
      args,
      overrides,
      forNode: nodeName
    });
  };
  if (nodeName === "root") {
    func.displayName = "PlasmicInfoCard";
  } else {
    func.displayName = `PlasmicInfoCard.${nodeName}`;
  }
  return func;
}

export const PlasmicInfoCard = Object.assign(
  // Top-level PlasmicInfoCard renders the root element
  makeNodeComponent("root"),
  {
    // Helper components rendering sub-elements
    iconWrapper: makeNodeComponent("iconWrapper"),
    titleWrapper: makeNodeComponent("titleWrapper"),
    descriptionWrapper: makeNodeComponent("descriptionWrapper"),
    activeGridHoverStyle: makeNodeComponent("activeGridHoverStyle"),
    lottie: makeNodeComponent("lottie"),

    // Metadata about props expected for PlasmicInfoCard
    internalVariantProps: PlasmicInfoCard__VariantProps,
    internalArgProps: PlasmicInfoCard__ArgProps
  }
);

export default PlasmicInfoCard;
